import re
from collections import deque
from decimal import Decimal

class ExpressionCalculator:
    # Replace Magic Number with Symbolic Constant
    OPERATOR_PRIORITY = [0, 3, 2, 1, -1, 1, 0, 2]
    OPERATORS = frozenset({'+', '-', '*', '/', '(', ')', '%'})
    LOGICAL_OR = frozenset({'+', '-', '*', '/', '(', 'E', 'e'})
    NEGATIVE_SIGN = '~'
    ZERO = "0"
    COMMA = ','
    OPEN_PAREN = '('
    CLOSE_PAREN = ')'
    EQUALS_SIGN = '='
    EMPTY_STRING = ''
    WHITESPACE_PATTERN = r"\s+"
    TRAILING_EQUALS_PATTERN = r"=$"
    UNEXPECTED_OPERATOR_ERROR_PREFIX = "Unexpected operator: "
    OPERATOR_MAPPING = {
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
        '*': lambda x, y: x * y,
        '/': lambda x, y: x / y,
        '%': lambda x, y: x % y,
    }

    def __init__(self):
        self.postfix_stack = deque()

    def calculate(self, expression):
        self.prepare(self.transform(expression))

        result_stack = deque()
        self.postfix_stack.reverse()

        while self.postfix_stack:
            current_op = self.postfix_stack.pop()
            if not self.is_operator(current_op):
                current_op = self._handle_positive_number(current_op)
                result_stack.append(current_op)
            else:
                second_value = result_stack.pop()
                first_value = result_stack.pop()

                first_value = self._normalize_value(first_value)
                second_value = self._normalize_value(second_value)

                temp_result = self._calculate(first_value, second_value, current_op)
                result_stack.append(str(temp_result))

        return float(eval("*".join(result_stack)))

    def prepare(self, expression):
        op_stack = deque([self.COMMA])
        arr = list(expression)
        current_index = 0
        count = 0

        for i, current_op in enumerate(arr):
            if self.is_operator(current_op):
                if count > 0:
                    self.postfix_stack.append("".join(arr[current_index: current_index + count]))
                peek_op = op_stack[-1]
                if current_op == self.CLOSE_PAREN:
                    while op_stack[-1] != self.OPEN_PAREN:
                        self.postfix_stack.append(str(op_stack.pop()))
                    op_stack.pop()
                else:
                    while current_op != self.OPEN_PAREN and peek_op != self.COMMA and self.compare(current_op, peek_op):
                        self.postfix_stack.append(str(op_stack.pop()))
                        peek_op = op_stack[-1]
                    op_stack.append(current_op)

                count = 0
                current_index = i + 1
            else:
                count += 1

        if self._should_append_number(arr, current_index, count):
            self.postfix_stack.append("".join(arr[current_index: current_index + count]))

        while op_stack[-1] != self.COMMA:
            self.postfix_stack.append(str(op_stack.pop()))

    @staticmethod
    def is_operator(c):
        return c in ExpressionCalculator.OPERATORS

    def compare(self, cur, peek):
        cur = self._apply_operator_mapping(cur)
        peek = self._apply_operator_mapping(peek)
        return self._get_operator_priority(peek) >= self._get_operator_priority(cur)

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        expression = ExpressionCalculator.OPERATOR_MAPPING[current_op]
        return expression(Decimal(first_value), Decimal(second_value))

    @staticmethod
    def transform(expression):
        expression = re.sub(ExpressionCalculator.WHITESPACE_PATTERN, ExpressionCalculator.EMPTY_STRING, expression)
        expression = re.sub(ExpressionCalculator.TRAILING_EQUALS_PATTERN, ExpressionCalculator.EMPTY_STRING, expression)
        arr = list(expression)

        for i, c in enumerate(arr):
            if c == '-':
                if i == 0 or arr[i - 1] in ExpressionCalculator.LOGICAL_OR:
                    arr[i] = ExpressionCalculator.NEGATIVE_SIGN

        return ExpressionCalculator._finalize_transformed_expression(arr)

    @staticmethod
    def _apply_operator_mapping(op):
        if op == '%':
            return '/'
        return op

    def _get_operator_priority(self, op):
        return ExpressionCalculator.OPERATOR_PRIORITY[ord(op) - 40]

    @staticmethod
    def _handle_positive_number(number_str):
        return number_str.replace(ExpressionCalculator.NEGATIVE_SIGN, '-')

    @staticmethod
    def _normalize_value(value):
        return value.replace(ExpressionCalculator.NEGATIVE_SIGN, '-')

    @staticmethod
    def _should_append_number(arr, current_index, count):
        return count > 1 or (count == 1 and not ExpressionCalculator.is_operator(arr[current_index]))

    @staticmethod
    def _finalize_transformed_expression(arr):
        first_char = arr[0]
        if first_char == ExpressionCalculator.NEGATIVE_SIGN and (len(arr) > 1 and arr[1] == ExpressionCalculator.OPEN_PAREN):
            arr[0] = '-'
            return ExpressionCalculator.ZERO + "".join(arr)
        return "".join(arr)
